<script setup>
/**
 * Pengajuan Cuti Karyawan — seluruh pengajuan cuti karyawan, khusus HR.
 *
 * Berbeda dari menu Cuti (pengajuan sendiri + antrean persetujuan): di sini
 * HR memantau semua karyawan. Keputusan HR diambil di halaman detail cuti
 * yang sama. Pola saringnya sama dengan Master Karyawan, dan kalender rentang
 * tanggalnya sama dengan Data Pengajuan.
 */
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { angka, rentang, statusBadge } from '../data/cutiStatus'
import { refreshCsrfToken } from '../data/session'
import { useListPersistence } from '../composables/useListPersistence'
import { NAVIGATION_ORIGIN, withNavigationOrigin } from '../data/navigationOrigin'

const PER_HALAMAN = 20
const router = useRouter()
const listPersistence = useListPersistence('PengajuanCutiKaryawan')

function buka(name) {
	router.push(
		withNavigationOrigin(
			{ name: 'CutiDetail', params: { name } },
			NAVIGATION_ORIGIN.PENGAJUAN_CUTI_KARYAWAN
		)
	)
}

// ---- Saring (pola bottom-sheet, sama seperti Master Karyawan) ---------------
const PILIHAN = [
	{ key: 'status', label: 'Status', ikon: ['M13 2 3 14h9l-1 8 10-12h-9l1-8z'] },
	{
		key: 'leave_type',
		label: 'Jenis Cuti',
		ikon: ['M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z', 'M14 2v6h6'],
	},
	{
		key: 'department',
		label: 'Departemen',
		ikon: ['M3 21h18', 'M5 21V7l7-4 7 4v14', 'M10 21v-6h4v6'],
	},
	{
		key: 'cabang',
		label: 'Cabang',
		ikon: [
			'M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0z',
			'M12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6z',
		],
	},
]
const JUDUL_PILIHAN = {
	status: 'Status',
	leave_type: 'Jenis Cuti',
	department: 'Departemen',
	cabang: 'Cabang',
}
const MULTI = ['status', 'leave_type', 'department', 'cabang']
const kosongkan = () => ({
	cari: '',
	status: [],
	leave_type: [],
	department: [],
	cabang: [],
	dari: '',
	sampai: '',
})
function salinSaringan(src) {
	const out = { cari: src.cari, dari: src.dari, sampai: src.sampai }
	for (const k of MULTI) out[k] = [...src[k]]
	return out
}

const showFilter = ref(false)
const showPilihan = ref('')
const terpakai = reactive({ ...kosongkan(), ...listPersistence.readSession({}).filters })
const draft = reactive(kosongkan())

const opsi = reactive({ status: [], leave_type: [], department: [], cabang: [] })
const pilihanAktif = computed(() => opsi[showPilihan.value] || [])
const jumlahSaringan = computed(
	() =>
		(terpakai.cari ? 1 : 0) +
		(terpakai.dari || terpakai.sampai ? 1 : 0) +
		MULTI.reduce((n, k) => n + terpakai[k].length, 0)
)

function ringkas(arr) {
	if (!arr.length) return ''
	return arr.length <= 2 ? arr.join(', ') : `${arr[0]} +${arr.length - 1}`
}
function pilihGanda(arr, nilai) {
	const i = arr.indexOf(nilai)
	if (i === -1) arr.push(nilai)
	else arr.splice(i, 1)
}
function openFilter() {
	Object.assign(draft, salinSaringan(terpakai))
	showFilter.value = true
}
function applyFilter() {
	Object.assign(terpakai, salinSaringan({ ...draft, cari: draft.cari.trim() }))
	listPersistence.writeSession({ filters: salinSaringan(terpakai) })
	showFilter.value = false
	reload()
}
function clearFilter() {
	Object.assign(draft, kosongkan())
	Object.assign(terpakai, kosongkan())
	listPersistence.clearSession()
	showFilter.value = false
	reload()
}

createResource({
	url: 'juragan.api.portal.cuti.get_opsi_pengajuan_karyawan',
	auto: true,
	onSuccess(d) {
		Object.assign(opsi, d || {})
	},
})

// ---- Kalender rentang Tanggal Mulai Cuti (sama dengan Data Pengajuan) -------
const showDateSheet = ref(false)
const calCursor = ref(new Date()) // bulan yang ditampilkan (tgl 1)
const rangeStart = ref('') // 'YYYY-MM-DD'
const rangeEnd = ref('')

const WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]

// Format lokal 'YYYY-MM-DD' (hindari pergeseran zona waktu dari toISOString).
function ymd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function parseYmd(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}
function formatDate(v) {
	const m = String(v || '').match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v || '')
}

// Ringkasan rentang untuk field di sheet filter.
const dateSummary = computed(() => {
	const a = draft.dari
	const b = draft.sampai
	if (a && b) return `${formatDate(a)} – ${formatDate(b)}`
	if (a) return `Dari ${formatDate(a)}`
	if (b) return `Sampai ${formatDate(b)}`
	return ''
})

function openDateSheet() {
	rangeStart.value = draft.dari
	rangeEnd.value = draft.sampai
	const d = parseYmd(draft.dari || ymd(new Date()))
	calCursor.value = new Date(d.getFullYear(), d.getMonth(), 1)
	showDateSheet.value = true
}

const calLabel = computed(
	() => `${MONTHS[calCursor.value.getMonth()]} ${calCursor.value.getFullYear()}`
)

// Sel kalender bulan aktif; null = padding awal pekan (mulai Senin).
const calDays = computed(() => {
	const year = calCursor.value.getFullYear()
	const month = calCursor.value.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7 // Senin = 0
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})

function prevMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() - 1, 1)
}
function nextMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() + 1, 1)
}

// Tap tanggal: tentukan mulai, lalu akhir (auto-tukar bila terbalik).
function pickDay(date) {
	const s = ymd(date)
	if (!rangeStart.value || (rangeStart.value && rangeEnd.value)) {
		rangeStart.value = s
		rangeEnd.value = ''
	} else if (s < rangeStart.value) {
		rangeEnd.value = rangeStart.value
		rangeStart.value = s
	} else {
		rangeEnd.value = s
	}
}

// Kelas tampilan tiap sel (endpoint / dalam rentang / hari ini / biasa).
function dayClass(date) {
	const s = ymd(date)
	const isStart = s === rangeStart.value
	const isEnd = s === rangeEnd.value
	if (isStart || isEnd) return 'rounded-full bg-primary font-semibold text-ui-onPrimary'
	if (rangeStart.value && rangeEnd.value && s > rangeStart.value && s < rangeEnd.value)
		return 'rounded-md bg-primary/10 text-primary'
	if (s === ymd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}

function clearDateRange() {
	rangeStart.value = ''
	rangeEnd.value = ''
}
// Simpan rentang ke draft (tetap di sheet filter setelah ini).
function applyDateRange() {
	draft.dari = rangeStart.value
	draft.sampai = rangeEnd.value
	showDateSheet.value = false
}

// ---- Data & pagination -----------------------------------------------------
const rows = ref([])
const start = ref(0)
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')

const list = createResource({
	url: 'juragan.api.portal.cuti.get_pengajuan_karyawan',
	auto: false,
	makeParams() {
		// Kunci kosong tidak dikirim — nilai undefined ter-serialisasi jadi "undefined".
		const p = { start: start.value, limit: PER_HALAMAN }
		if (terpakai.cari) p.cari = terpakai.cari
		for (const k of MULTI) if (terpakai[k].length) p[k] = JSON.stringify(terpakai[k])
		if (terpakai.dari) p.dari = terpakai.dari
		if (terpakai.sampai) p.sampai = terpakai.sampai
		return p
	},
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === PER_HALAMAN
		loading.value = false
	},
	onError(err) {
		error.value = err?.messages?.[0] || err?.message || String(err)
		loading.value = false
	},
})

function reload() {
	error.value = ''
	start.value = 0
	loading.value = true
	list.fetch()
}
function loadMore() {
	start.value += PER_HALAMAN
	loading.value = true
	list.fetch()
}

onMounted(async () => {
	await refreshCsrfToken()
	reload()
})
</script>

